<script lang="ts">
	import { createEventDispatcher, getContext } from 'svelte';
	import { toast } from 'svelte-sonner';

	import Modal from '$lib/components/common/Modal.svelte';
	import XMark from '$lib/components/icons/XMark.svelte';
	import Spinner from '$lib/components/common/Spinner.svelte';

	import { createCalendar } from '$lib/apis/calendar';

	const i18n = getContext('i18n');
	const dispatch = createEventDispatcher();

	export let show = false;

	let name = '';
	let color = '#3b82f6';
	let loading = false;

	const PRESET_COLORS = [
		'#3b82f6', // blue
		'#ef4444', // red
		'#22c55e', // green
		'#f59e0b', // amber
		'#8b5cf6', // violet
		'#ec4899', // pink
		'#06b6d4', // cyan
		'#f97316' // orange
	];

	function reset() {
		name = '';
		color = '#3b82f6';
		loading = false;
	}

	$: if (show) reset();

	const submitHandler = async () => {
		if (!name.trim()) {
			toast.error($i18n.t('Name is required'));
			return;
		}

		loading = true;
		try {
			const result = await createCalendar(localStorage.token, {
				name: name.trim(),
				color
			});
			if (result) {
				toast.success($i18n.t('Calendar created'));
				dispatch('created', result);
				show = false;
			}
		} catch (err) {
			toast.error(`${err}`);
		} finally {
			loading = false;
		}
	};
</script>

<Modal ariaLabel={$i18n.t('New Calendar')} size="sm" bind:show>
	<div>
		<!-- Header -->
		<div class="flex justify-between items-center dark:text-gray-100 px-4 pt-3 pb-1">
			<h3 class="text-base font-normal">{$i18n.t('New Calendar')}</h3>
			<button
				class="self-center shrink-0 ml-2"
				aria-label={$i18n.t('Close')}
				on:click={() => (show = false)}
			>
				<XMark className="size-4" />
			</button>
		</div>

		<!-- Form -->
		<div class="px-4 pb-2 flex flex-col gap-3">
			<!-- Name -->
			<div>
				<label for="calendar-name" class="block mb-1 text-xs text-gray-500">{$i18n.t('Name')}</label
				>
				<input
					id="calendar-name"
					class="w-full text-sm bg-transparent outline-hidden placeholder:text-gray-300 dark:placeholder:text-gray-700"
					type="text"
					bind:value={name}
					placeholder={$i18n.t('Calendar name')}
					on:keydown={(e) => {
						if (e.key === 'Enter') submitHandler();
					}}
				/>
			</div>

			<!-- Color -->
			<div>
				<div class="mb-1 text-xs text-gray-500">{$i18n.t('Color')}</div>
				<div class="flex items-center gap-2 flex-wrap">
					{#each PRESET_COLORS as c}
						<button
							class="size-6 rounded-full transition-all border-2 {color === c
								? 'border-gray-800 dark:border-white scale-110'
								: 'border-transparent hover:scale-110'}"
							style="background-color: {c};"
							on:click={() => (color = c)}
							aria-label={c}
						/>
					{/each}

					<label
						class="size-6 rounded-full overflow-hidden cursor-pointer border-2 transition-all {!PRESET_COLORS.includes(
							color
						)
							? 'border-gray-800 dark:border-white scale-110'
							: 'border-transparent hover:scale-110'}"
						style="background-color: {color};"
						title={$i18n.t('Custom color')}
					>
						<input
							type="color"
							bind:value={color}
							aria-label={$i18n.t('Custom color')}
							class="opacity-0 w-0 h-0 absolute"
						/>
					</label>
				</div>
			</div>
		</div>

		<!-- Bottom toolbar -->
		<div class="flex items-center justify-end px-4 pb-3.5 pt-2 gap-2">
			<button
				class="flex h-7 shrink-0 items-center justify-center gap-1.5 rounded-lg px-2.5 text-xs font-normal text-gray-600 transition hover:bg-gray-100 hover:text-gray-900 disabled:opacity-60 dark:text-gray-400 dark:hover:bg-gray-850 dark:hover:text-white"
				type="button"
				on:click={() => (show = false)}
			>
				{$i18n.t('Cancel')}
			</button>
			<button
				class="flex h-7 shrink-0 items-center justify-center gap-1.5 rounded-lg bg-gray-900 px-2.5 text-xs font-normal text-white transition hover:bg-black disabled:opacity-60 dark:bg-gray-100 dark:text-gray-900 dark:hover:bg-white disabled:cursor-not-allowed"
				on:click={submitHandler}
				type="button"
				disabled={loading}
			>
				{$i18n.t('Create')}
				{#if loading}
					<span class="shrink-0"><Spinner className="size-3" /></span>
				{/if}
			</button>
		</div>
	</div>
</Modal>
